from pathlib import Path
import sys
from ritmo_v1_patch_utils import js_function_bounds

root=Path(sys.argv[1])
app=root/'public'/'app.js'; cssp=root/'public'/'styles.css'
a=app.read_text(); css=cssp.read_text()

def replace_func(src,name,code):
    p,q=js_function_bounds(src,name); return src[:p]+code+src[q:]

# Dois perfis financeiros claros: Pessoal e Casal. A troca continua usando a
# mesma lógica de escopo e pré-carregamento já existente; este patch é só UI.
profile_overview=r'''function walletOverviewHtml(){const d=state.data||{},w=d.wallet||{},sh=d.sharing||{},me=d.profile||{},shared=d.scope==='shared',active=sharedActive(),partner=sh.partner||{},meFirst=(me.name||'Você').split(' ')[0],partnerFirst=(partner.name||'Parceiro').split(' ')[0],balance=shared?Number(w.shared_balance||0):Number(w.personal_balance||0),movement=shared?Number(w.shared_transfers||0):Number(w.sent_to_shared||0);return `<section class="finance-profile-shell ${shared?'couple':'personal'}"><div class="finance-profile-switch" role="tablist" aria-label="Perfil financeiro"><button type="button" role="tab" aria-selected="${!shared}" class="${!shared?'active':''}" data-scope="personal"><span class="switch-avatar personal">${initials(me.name||'Você')}</span><span><small>Perfil</small><strong>Pessoal</strong></span></button>${active?`<button type="button" role="tab" aria-selected="${shared}" class="${shared?'active':''}" data-scope="shared"><span class="switch-avatar couple">${initials(meFirst)}${initials(partnerFirst)}</span><span><small>Perfil</small><strong>Casal</strong></span></button>`:''}</div><article class="finance-profile-card"><div class="finance-profile-top"><div class="finance-profile-identity">${shared?`<div class="couple-profile-avatars"><span>${initials(me.name||'Você')}</span><span>${initials(partner.name||'Parceiro')}</span></div>`:`<span class="solo-profile-avatar">${initials(me.name||'Você')}</span>`}<div><small>${shared?'PERFIL DO CASAL':'SEU PERFIL'}</small><h2>${shared?`${esc(meFirst)} & ${esc(partnerFirst)}`:esc(me.name||'Meu Ritmo')}</h2><p>${shared?'Dinheiro em comum, sem misturar o que é pessoal.':'Seu dinheiro, suas decisões e seu histórico.'}</p></div></div>${shared?`<span class="profile-badge shared">${ic('users',13)} Casal</span>`:`<span class="profile-badge personal">${ic('user',13)} Pessoal</span>`}</div><div class="finance-profile-balance"><span>${shared?'Saldo do casal':'Meu saldo'}</span><strong>${money(balance)}</strong><small>${shared?`${money(movement)} em contribuições`:`${money(movement)} enviados ao casal`}</small></div><div class="finance-profile-actions">${active?`<button type="button" class="profile-action primary" data-transfer-new>${ic('up',14)}<span>Transferir</span></button>`:''}<button type="button" class="profile-action" data-page="reports">${ic('doc',14)}<span>Relatório</span></button>${shared?`<button type="button" class="profile-action" data-page="sharing">${ic('users',14)}<span>Detalhes</span></button>`:''}</div></article></section>`}'''
a=replace_func(a,'walletOverviewHtml',profile_overview)

home=r'''function homePage(){const shared=state.data.scope==='shared',s=currentStats(),commitments=[...state.data.expenses.filter(x=>!expenseIsRealized(x)&&(x.due_date||x.date)).map(x=>({type:'expense',date:x.due_date||x.date,item:x})),...state.data.debts.filter(x=>debtCurrentBalance(x)>0&&x.due_date).map(x=>({type:'debt',date:x.due_date,item:x}))].sort((a,b)=>a.date.localeCompare(b.date)).slice(0,4),partner=state.data.sharing?.partner?.name?.split(' ')[0]||'seu parceiro';return `${walletOverviewHtml()}<div class="profile-page-intro"><span class="eyebrow">RITMO</span><h1>${shared?'Nosso Ritmo':`Olá, ${esc(state.data.profile.name.split(' ')[0])}`}</h1><p>${shared?`O que vocês compartilham, organizado com ${esc(partner)}.`:'Seu dinheiro pessoal, organizado de forma simples.'}</p></div><section class="money-light-strip"><div class="main"><small>${shared?'Disponível do casal':'Disponível pessoal'}</small><strong>${money(s.balance)}</strong></div><div><small>A receber</small><b>${money(s.receivable)}</b></div><div><small>A pagar</small><b>${money(s.pending)}</b></div><div><small>Projeção</small><b>${money(s.forecast)}</b></div></section><section class="flow-light-grid"><article class="flow-light-card income"><span class="flow-light-icon">${ic('up',16)}</span><div><small>ENTRADAS</small><strong>${money(s.income)}</strong><p>Receita real</p></div></article><article class="flow-light-card expense"><span class="flow-light-icon">${ic('down',16)}</span><div><small>SAÍDAS</small><strong>${money(s.paid)}</strong><p>Pagamentos realizados</p></div></article><article class="flow-light-card pending"><span class="flow-light-icon">${ic('calendar',16)}</span><div><small>PENDENTE</small><strong>${money(s.pending)}</strong><p>${s.pendingCount} compromisso(s)</p></div></article><article class="flow-light-card debt"><span class="flow-light-icon">${ic('wallet',16)}</span><div><small>DÍVIDAS</small><strong>${money(s.debt)}</strong><p>Saldo devedor</p></div></article></section><div class="grid2 compact-home-grid profile-lower-grid"><div class="panel light-panel"><div class="panel-title"><div><h3>Próximos compromissos</h3><small>Contas e dívidas com vencimento</small></div><button class="mini-btn" data-page="calendar">Calendário</button></div><div class="list">${commitments.length?commitments.map(x=>rowHtml(x.item,x.type)).join(''):`<div class="empty">Nenhum compromisso com vencimento. ✨</div>`}</div></div><div class="panel light-panel"><div class="panel-title"><div><h3>${shared?'Contribuições recentes':'Transferências'}</h3><small>${shared?'Quem colocou dinheiro no casal':'Movimentações para o casal'}</small></div><button class="mini-btn" data-page="reports">Relatório</button></div>${shared?walletContributionRows():transferHistoryHtml(4)}</div></div>`}'''
a=replace_func(a,'homePage',home)

css += r'''

/* Ritmo V1 — perfis financeiros com UI Light */
.finance-profile-shell{margin:4px 0 20px}.finance-profile-switch{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:5px;padding:5px;border-radius:18px;background:color-mix(in srgb,var(--surface2) 82%,transparent);max-width:430px;margin:0 0 11px}.finance-profile-switch:has(button:only-child){grid-template-columns:1fr}.finance-profile-switch button{border:0;background:transparent;color:var(--muted);border-radius:14px;min-height:48px;padding:7px 10px;display:flex;align-items:center;gap:9px;text-align:left;cursor:pointer;transition:background .18s ease,color .18s ease,transform .18s ease}.finance-profile-switch button:active{transform:scale(.985)}.finance-profile-switch button.active{background:var(--surface-solid);color:var(--text);box-shadow:0 5px 18px rgba(0,0,0,.055)}.finance-profile-switch button>span:last-child{min-width:0}.finance-profile-switch button small{display:block;font-size:7px;letter-spacing:.09em;text-transform:uppercase;color:var(--muted);line-height:1}.finance-profile-switch button strong{display:block;font-size:10px;margin-top:4px}.switch-avatar{width:32px;height:32px;border-radius:11px;display:grid;place-items:center;font-size:9px;font-weight:800;flex:0 0 auto}.switch-avatar.personal{background:color-mix(in srgb,var(--primary) 10%,var(--surface2));color:var(--primary)}.switch-avatar.couple{background:color-mix(in srgb,var(--sage) 13%,var(--surface2));color:var(--green);font-size:7px;letter-spacing:-.08em}.finance-profile-card{position:relative;overflow:hidden;border-radius:24px;padding:18px;background:linear-gradient(145deg,color-mix(in srgb,var(--surface-solid) 94%,var(--primary) 6%),var(--surface-solid));box-shadow:0 14px 34px rgba(0,0,0,.075);border:1px solid color-mix(in srgb,var(--line) 68%,transparent)}.finance-profile-shell.couple .finance-profile-card{background:linear-gradient(145deg,color-mix(in srgb,var(--surface-solid) 92%,var(--sage) 8%),var(--surface-solid))}.finance-profile-card:after{content:'';position:absolute;width:190px;height:190px;border-radius:50%;right:-82px;top:-105px;border:1px solid color-mix(in srgb,var(--primary) 11%,transparent);box-shadow:0 0 0 28px color-mix(in srgb,var(--primary) 2.5%,transparent),0 0 0 56px color-mix(in srgb,var(--primary) 2%,transparent);pointer-events:none}.finance-profile-shell.couple .finance-profile-card:after{border-color:color-mix(in srgb,var(--green) 13%,transparent);box-shadow:0 0 0 28px color-mix(in srgb,var(--green) 2.5%,transparent),0 0 0 56px color-mix(in srgb,var(--green) 2%,transparent)}.finance-profile-top{position:relative;z-index:1;display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.finance-profile-identity{display:flex;align-items:center;gap:11px;min-width:0}.finance-profile-identity>div:last-child{min-width:0}.finance-profile-identity small{display:block;color:var(--primary);font-size:7px;font-weight:800;letter-spacing:.14em}.finance-profile-shell.couple .finance-profile-identity small{color:var(--green)}.finance-profile-identity h2{font-size:15px;margin:4px 0 2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.finance-profile-identity p{font-size:8px;color:var(--muted);margin:0;line-height:1.4}.solo-profile-avatar,.couple-profile-avatars span{width:42px;height:42px;border-radius:14px;display:grid;place-items:center;font-weight:800;font-size:11px;background:color-mix(in srgb,var(--primary) 11%,var(--surface2));color:var(--primary);border:1px solid color-mix(in srgb,var(--primary) 12%,transparent)}.couple-profile-avatars{display:flex;align-items:center;padding-right:8px}.couple-profile-avatars span{background:color-mix(in srgb,var(--sage) 14%,var(--surface2));color:var(--green);border-color:color-mix(in srgb,var(--green) 12%,transparent)}.couple-profile-avatars span+span{margin-left:-10px;box-shadow:0 0 0 3px var(--surface-solid)}.profile-badge{display:inline-flex;align-items:center;gap:5px;padding:6px 8px;border-radius:999px;font-size:7px;font-weight:800;white-space:nowrap}.profile-badge.personal{background:color-mix(in srgb,var(--primary) 8%,transparent);color:var(--primary)}.profile-badge.shared{background:color-mix(in srgb,var(--green) 8%,transparent);color:var(--green)}.finance-profile-balance{position:relative;z-index:1;margin:22px 0 16px}.finance-profile-balance>span{display:block;font-size:8px;color:var(--muted)}.finance-profile-balance>strong{display:block;font-size:31px;line-height:1.05;letter-spacing:-.035em;margin:5px 0}.finance-profile-balance>small{font-size:8px;color:var(--muted)}.finance-profile-actions{position:relative;z-index:1;display:flex;gap:7px;flex-wrap:wrap}.profile-action{border:0;background:color-mix(in srgb,var(--surface2) 88%,transparent);color:var(--text);border-radius:12px;min-height:38px;padding:8px 11px;display:inline-flex;align-items:center;gap:7px;font:inherit;font-size:8px;font-weight:700;cursor:pointer;transition:transform .16s ease,background .16s ease}.profile-action:active{transform:scale(.97)}.profile-action.primary{background:color-mix(in srgb,var(--primary) 12%,var(--surface2));color:var(--primary)}.finance-profile-shell.couple .profile-action.primary{background:color-mix(in srgb,var(--green) 12%,var(--surface2));color:var(--green)}.profile-page-intro{margin:3px 0 14px}.profile-page-intro h1{font-size:28px;letter-spacing:-.04em;margin:5px 0 4px}.profile-page-intro p{font-size:10px;color:var(--muted);margin:0;line-height:1.45}.money-light-strip{display:grid;grid-template-columns:1.35fr repeat(3,1fr);gap:0;background:transparent;border-top:1px solid var(--line);border-bottom:1px solid var(--line);margin:0 0 14px}.money-light-strip>div{padding:11px 10px;min-width:0}.money-light-strip>div+div{border-left:1px solid color-mix(in srgb,var(--line) 70%,transparent)}.money-light-strip small{display:block;font-size:7px;color:var(--muted);white-space:nowrap}.money-light-strip strong,.money-light-strip b{display:block;font-size:11px;margin-top:4px;white-space:nowrap}.money-light-strip .main strong{font-size:15px}.flow-light-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;margin-bottom:14px}.flow-light-card{display:flex;align-items:center;gap:10px;padding:11px 12px;border-radius:16px;background:color-mix(in srgb,var(--surface-solid) 96%,transparent);border:1px solid color-mix(in srgb,var(--line) 62%,transparent);min-width:0;box-shadow:0 4px 13px rgba(0,0,0,.025)}.flow-light-icon{width:34px;height:34px;border-radius:11px;display:grid;place-items:center;flex:0 0 auto}.flow-light-card.income .flow-light-icon{color:var(--green);background:color-mix(in srgb,var(--green) 10%,var(--surface2))}.flow-light-card.expense .flow-light-icon{color:var(--coral);background:color-mix(in srgb,var(--coral) 10%,var(--surface2))}.flow-light-card.pending .flow-light-icon{color:var(--gold);background:color-mix(in srgb,var(--gold) 10%,var(--surface2))}.flow-light-card.debt .flow-light-icon{color:var(--primary);background:color-mix(in srgb,var(--primary) 9%,var(--surface2))}.flow-light-card>div{min-width:0}.flow-light-card small{display:block;font-size:7px;letter-spacing:.14em;color:var(--muted);font-weight:800}.flow-light-card strong{display:block;font-size:16px;margin:4px 0 2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.flow-light-card p{font-size:7.5px;color:var(--muted);margin:0}.light-panel{border-color:color-mix(in srgb,var(--line) 58%,transparent)!important;box-shadow:none!important}.profile-lower-grid{gap:9px}
@media(max-width:720px){.finance-profile-shell{margin-top:0}.finance-profile-card{border-radius:21px;padding:15px}.finance-profile-balance{margin:18px 0 14px}.finance-profile-balance>strong{font-size:28px}.profile-page-intro h1{font-size:26px}.money-light-strip{grid-template-columns:repeat(2,minmax(0,1fr));border:1px solid color-mix(in srgb,var(--line) 68%,transparent);border-radius:16px;overflow:hidden}.money-light-strip>div{padding:10px 11px}.money-light-strip>div+div{border-left:0}.money-light-strip>div:nth-child(even){border-left:1px solid color-mix(in srgb,var(--line) 65%,transparent)}.money-light-strip>div:nth-child(n+3){border-top:1px solid color-mix(in srgb,var(--line) 65%,transparent)}.flow-light-grid{gap:6px}.flow-light-card{padding:10px}.flow-light-icon{width:31px;height:31px}.flow-light-card strong{font-size:14px}.profile-action{flex:1;justify-content:center}.finance-profile-switch{max-width:none}.profile-badge{display:none}.finance-profile-identity p{max-width:220px}}
@media(min-width:980px){.finance-profile-shell{display:grid;grid-template-columns:260px minmax(0,1fr);gap:12px;align-items:stretch}.finance-profile-switch{grid-template-columns:1fr;align-content:start;margin:0;padding:7px}.finance-profile-card{min-height:190px}.flow-light-grid{grid-template-columns:repeat(4,minmax(0,1fr))}.profile-page-intro{margin-top:18px}}
@media(prefers-reduced-motion:reduce){.finance-profile-switch button,.profile-action{transition:none!important}}
'''

if 'finance-profile-shell' not in a or 'flow-light-grid' not in a: raise SystemExit('UI Light de perfis não aplicada')
app.write_text(a); cssp.write_text(css)
print('Ritmo V1: Pessoal e Casal ganharam perfis financeiros próprios com UI Light.')
